+            "test",
+            PromptType::Select {
+                options: options.clone(),
+            },
+            Some("no"),
+        );
+
+        // Verify the default index resolves to 1 (the "no" option)
+        let default_idx = prompt
+            .default
+            .as_ref()
+            .and_then(|d| options.iter().position(|o| o.value == *d))
+            .unwrap_or(0);
+        assert_eq!(default_idx, 1);
+    }
+
+    #[test]
+    fn prompt_yes_no_default_falls_back_to_zero() {
+        let options = vec![
+            PromptOption {
+                label: "Yes (y)".to_string(),
+                value: "yes".to_string(),
+            },
+            PromptOption {
+                label: "No (n)".to_string(),
+                value: "no".to_string(),
+            },
+        ];
+        let prompt = make_prompt(
+            "test",
+            PromptType::Select {
+                options: options.clone(),
+            },
+            None,
+        );
+
+        // With no default, index should fall back to 0
+        let default_idx = prompt
+            .default
+            .as_ref()
+            .and_then(|d| options.iter().position(|o| o.value == *d))
+            .unwrap_or(0);
+        assert_eq!(default_idx, 0);
+    }
